script:
frappe.ui.form.on('Sales Team Tracker', {
    refresh: function(frm) {
        frm.disable_save();
        frm.get_field('map_html').$wrapper.html(`
            <div style="background: #f8f9fa; padding: 20px; border-radius: 8px; border: 1px solid #ddd; margin-bottom: 15px;">
                <div class="row">
                    <div class="col-md-3"><label>Start Date</label><input type="date" id="map-start-date" class="form-control input-sm" value="${frappe.datetime.get_today()}"></div>
                    <div class="col-md-3"><label>End Date</label><input type="date" id="map-end-date" class="form-control input-sm" value="${frappe.datetime.get_today()}"></div>
                    <div class="col-md-3"><label>Salesperson Filter</label><select id="map-person" class="form-control input-sm"><option value="All">All Staff</option></select></div>
                    <div class="col-md-3" style="margin-top: 24px;">
                        <button class="btn btn-primary btn-sm" id="btn-refresh-map">Fetch Data</button>
                        <button class="btn btn-success btn-sm" id="btn-replay-route" style="margin-left: 10px;">▶ Replay</button>
                        <button class="btn btn-warning btn-sm" id="btn-pause-replay" style="margin-left: 5px;">⏸ Pause</button>
                    </div>
                </div>
            </div>
            <div id="map-status" style="margin-bottom: 10px; font-weight: bold; color: #1976D2;">Initializing Map Engine...</div>
            <div id="salesMap" style="height: 700px; width: 100%; border-radius: 8px; border: 2px solid #ccc; z-index: 1;"></div>
        `);

        if (!$('link[href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"]').length) {
            $('head').append('<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" type="text/css" />');
        }
        frappe.require("https://unpkg.com/leaflet@1.9.4/dist/leaflet.js", function() { init_advanced_map(frm); });
    }
});

function init_advanced_map(frm) {
    let map = L.map('salesMap').setView([-6.8, 39.2], 12); 
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', { attribution: 'OSM' }).addTo(map);
    let markersLayer = new L.FeatureGroup().addTo(map);

    window.currentPaths = {}; 
    window.replayTimer = null;

    frappe.call({
        method: 'frappe.client.get_list',
        args: { doctype: 'User', fields: ['name', 'full_name'], filters: [['enabled', '=', 1]], limit_page_length: 500 },
        callback: function(r) {
            if (r.message) {
                let dropdown = document.getElementById('map-person');
                r.message.forEach(u => {
                    let opt = document.createElement("option");
                    opt.value = u.name; opt.text = u.full_name; dropdown.add(opt);
                });
            }
        }
    });

    function fetch_locations() {
        if(window.replayTimer) clearInterval(window.replayTimer);
        document.getElementById('map-status').innerText = "Querying Server Database...";
        markersLayer.clearLayers();

        let startDate = document.getElementById('map-start-date').value + " 00:00:00";
        let endDate = document.getElementById('map-end-date').value + " 23:59:59"; 
        let selectedPerson = document.getElementById('map-person').value;

        frappe.call({
            method: 'sfa_crm.api.get_tracker_data',
            args: { start_date: startDate, end_date: endDate, sales_person: selectedPerson },
            callback: function(r) {
                if (r.message && r.message.length > 0) {
                    window.currentPaths = {};
                    r.message.forEach(log => {
                        if (!window.currentPaths[log.user_name]) window.currentPaths[log.user_name] = [];
                        let lat = parseFloat(log.latitude), lng = parseFloat(log.longitude);
                        if (!isNaN(lat) && !isNaN(lng)) {
                            window.currentPaths[log.user_name].push({ lat, lng, time: log.timestamp, activity: log.activity });
                        }
                    });
                    render_static_map();
                } else {
                    document.getElementById('map-status').innerText = `No GPS data found in this date range.`;
                    window.currentPaths = {};
                }
            }
        });
    }

    function render_static_map() {
        markersLayer.clearLayers();
        let bounds = [];
        Object.keys(window.currentPaths).forEach(person => {
            let pathData = window.currentPaths[person];
            if(pathData.length === 0) return;
            let latlngs = pathData.map(p => [p.lat, p.lng]);
            L.polyline(latlngs, {color: '#D32F2F', weight: 4, opacity: 0.8}).addTo(markersLayer); 
            pathData.forEach(p => {
                let isActivity = p.activity && (p.activity.includes("Took") || p.activity.includes("Registered"));
                if (isActivity) {
                    L.circleMarker([p.lat, p.lng], { radius: 8, color: "green", fillColor: 'white', fillOpacity: 1 }).addTo(markersLayer)
                     .bindPopup(`<b>${person}</b><br>⏱️ ${p.time}<br>🏃 ${p.activity}`);
                } else {
                    L.circleMarker([p.lat, p.lng], { radius: 3, color: "black", fillColor: 'white', fillOpacity: 1 }).addTo(markersLayer);
                }
                bounds.push([p.lat, p.lng]);
            });
        });
        if (bounds.length > 0) map.fitBounds(bounds, { padding: [50, 50] });
        document.getElementById('map-status').innerText = `Showing optimized routes for ${Object.keys(window.currentPaths).length} rep(s).`;
    }

    document.getElementById('btn-refresh-map').addEventListener('click', fetch_locations);

    document.getElementById('btn-replay-route').addEventListener('click', function() {
        let keys = Object.keys(window.currentPaths);
        if(keys.length === 0) return;
        markersLayer.clearLayers();
        document.getElementById('map-status').innerText = "▶ Replaying Historical Route...";

        let playbackMarkers = {};
        let index = 0;
        let maxLength = Math.max(...keys.map(k => window.currentPaths[k].length));

        keys.forEach(p => {
            let firstPt = window.currentPaths[p][0];
            playbackMarkers[p] = {
                marker: L.marker([firstPt.lat, firstPt.lng]).addTo(markersLayer),
                line: L.polyline([[firstPt.lat, firstPt.lng]], {color: '#1976D2', weight: 5}).addTo(markersLayer)
            };
            playbackMarkers[p].marker.bindTooltip(`<b>${p}</b><br>${firstPt.time}`).openTooltip();
        });

        if(window.replayTimer) clearInterval(window.replayTimer);
        window.replayTimer = setInterval(() => {
            index++;
            if (index >= maxLength) {
                clearInterval(window.replayTimer);
                document.getElementById('map-status').innerText = "✅ Route Replay Complete.";
                render_static_map(); // re-plot activity dots at the end
                return;
            }
            keys.forEach(p => {
                let pathArr = window.currentPaths[p];
                if (index < pathArr.length) {
                    let pt = pathArr[index];
                    let latlng = [pt.lat, pt.lng];
                    playbackMarkers[p].marker.setLatLng(latlng);
                    playbackMarkers[p].marker.setTooltipContent(`<b>${p}</b><br>${pt.time}`);
                    playbackMarkers[p].line.addLatLng(latlng);
                }
            });
        }, 500); 
    });

    document.getElementById('btn-pause-replay').addEventListener('click', function() {
        if(window.replayTimer) {
            clearInterval(window.replayTimer);
            document.getElementById('map-status').innerText = "⏸ Replay Paused.";
        }
    });

    fetch_locations();
}

frappe.ui.form.on("Salesperson Location Log", {
	refresh(frm) {
        if (frm.doc.latitude && frm.doc.longitude) {
            frm.add_custom_button(__('View on Google Maps'), () => {
                window.open(`https://www.google.com/maps?q=${frm.doc.latitude},${frm.doc.longitude}`, '_blank');
            }, 'Map');
        }
	}
});

frappe.ui.form.on("Salesperson Tracking Map", {
	refresh(frm) {
        frm.get_field("map_view").$wrapper.html(`
            <div style="border: 1px solid #d1d8dd; border-radius: 4px; padding: 10px;">
                <h4 style="margin-top: 0;">Salesperson Real-Time Location Map</h4>
                <div id="salesperson_leaflet_map" style="height: 600px; width: 100%; z-index: 1;"></div>
            </div>
        `);
        setTimeout(() => {
            frm.trigger('render_map');
        }, 300);
    },

    render_map(frm) {
        frappe.call({
            method: "frappe.client.get_list",
            args: {
                doctype: "Salesperson Location Log",
                fields: ["sales_person", "latitude", "longitude", "timestamp", "activity"],
                limit_page_length: 500,
                order_by: "timestamp desc"
            },
            callback: function(r) {
                let logs = r.message || [];
                let map_div = frm.get_field("map_view").$wrapper.find('#salesperson_leaflet_map')[0];
                if (!map_div) return;

                if (frm.map_instance) frm.map_instance.remove();

                let centerLat = -6.3690;
                let centerLng = 34.8888;
                if (logs.length > 0 && logs[0].latitude) {
                    centerLat = parseFloat(logs[0].latitude);
                    centerLng = parseFloat(logs[0].longitude);
                }

                frm.map_instance = L.map(map_div).setView([centerLat, centerLng], 12);
                L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
                    attribution: '© OpenStreetMap'
                }).addTo(frm.map_instance);

                logs.forEach(log => {
                    let lat = parseFloat(log.latitude);
                    let lng = parseFloat(log.longitude);
                    if (lat && lng) {
                        // Create a circle marker for tracking points
                        L.circleMarker([lat, lng], {
                            radius: 6,
                            fillColor: "#ff7800",
                            color: "#000",
                            weight: 1,
                            opacity: 1,
                            fillOpacity: 0.8
                        }).addTo(frm.map_instance)
                        .bindPopup(`<b>User:</b> ${log.sales_person}<br><b>Time:</b> ${log.timestamp}<br><b>Activity:</b> ${log.activity}`);
                    }
                });
            }
        });
    }
});

frappe.ui.form.on('Sales Team Tracker', {
    refresh: function(frm) {
        frm.disable_save();

        // Inject Custom Modern CSS
        if (!document.getElementById("modern-map-styles")) {
            $('head').append(`
                <style id="modern-map-styles">
                    .modern-stat-card { background: white; border-radius: 10px; padding: 15px; text-align: center; box-shadow: 0 4px 6px rgba(0,0,0,0.05); border: 1px solid #f0f0f0; flex: 1; margin: 0 5px; }
                    .stat-value { font-size: 22px; font-weight: 900; color: #D32F2F; margin-bottom: 5px; }
                    .stat-label { font-size: 11px; color: #888; text-transform: uppercase; letter-spacing: 1px; font-weight: bold; }
                    .pulse-marker { background: #1976D2; border-radius: 50%; box-shadow: 0 0 0 0 rgba(25, 118, 210, 1); animation: pulse 1.5s infinite; }
                    @keyframes pulse { 0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(25, 118, 210, 0.7); } 70% { transform: scale(1); box-shadow: 0 0 0 10px rgba(25, 118, 210, 0); } 100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(25, 118, 210, 0); } }
                </style>
            `);
        }

        frm.get_field('map_html').$wrapper.html(`
            <div style="background: #f8f9fa; padding: 20px; border-radius: 12px; border: 1px solid #ddd; margin-bottom: 15px;">
                <div class="row align-items-end">
                    <div class="col-md-3">
                        <label class="text-muted text-uppercase" style="font-size:11px;font-weight:bold;">Start Date</label>
                        <input type="date" id="map-start-date" class="form-control" style="border-radius:8px;" value="${frappe.datetime.get_today()}">
                    </div>
                    <div class="col-md-3">
                        <label class="text-muted text-uppercase" style="font-size:11px;font-weight:bold;">End Date</label>
                        <input type="date" id="map-end-date" class="form-control" style="border-radius:8px;" value="${frappe.datetime.get_today()}">
                    </div>
                    <div class="col-md-3">
                        <label class="text-muted text-uppercase" style="font-size:11px;font-weight:bold;">Salesperson</label>
                        <select id="map-person" class="form-control" style="border-radius:8px;"><option value="All">All Staff</option></select>
                    </div>
                    <div class="col-md-3">
                        <button class="btn btn-primary w-100" id="btn-refresh-map" style="border-radius:8px; font-weight:bold;">
                            <i class="fa fa-refresh"></i> Fetch Route Data
                        </button>
                    </div>
                </div>
            </div>

            <!-- Modern Dashboard Summary -->
            <div class="row" style="margin-bottom: 15px; display: flex;">
                <div class="modern-stat-card"><div class="stat-value" id="stat-dist">0 km</div><div class="stat-label">Total Distance</div></div>
                <div class="modern-stat-card"><div class="stat-value" id="stat-visits">0</div><div class="stat-label">Total Visits</div></div>
                <div class="modern-stat-card"><div class="stat-value" id="stat-pings">0</div><div class="stat-label">GPS Pings</div></div>
            </div>

            <div style="background: white; padding: 10px; border-radius: 12px; border: 1px solid #ddd;">
                <div class="text-center" style="margin-bottom: 10px;">
                    <button class="btn btn-sm" id="btn-play" style="background:#e8f5e9; color:#2e7d32; font-weight:bold; border-radius:20px; padding: 5px 15px;">▶ Play Route</button>
                    <button class="btn btn-sm" id="btn-pause" style="background:#fff3e0; color:#f57c00; font-weight:bold; border-radius:20px; padding: 5px 15px; margin-left:8px;">⏸ Pause</button>
                    <button class="btn btn-sm" id="btn-stop" style="background:#ffebee; color:#c62828; font-weight:bold; border-radius:20px; padding: 5px 15px; margin-left:8px;">⏹ Stop</button>
                    <span id="map-status" style="margin-left: 15px; font-weight: bold; color: #1976D2; font-size: 12px;">Ready.</span>
                </div>
                <div id="salesMap" style="height: 600px; width: 100%; border-radius: 8px; z-index: 1;"></div>
            </div>
        `);

        if (!$('link[href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css"]').length) {
            $('head').append('<link rel="stylesheet" href="https://unpkg.com/leaflet@1.9.4/dist/leaflet.css" type="text/css" />');
        }
        frappe.require("https://unpkg.com/leaflet@1.9.4/dist/leaflet.js", function() { init_advanced_map(frm); });
    }
});

function init_advanced_map(frm) {
    let map = L.map('salesMap').setView([-6.8, 39.2], 12); 
    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', { attribution: '© OpenStreetMap' }).addTo(map);
    let markersLayer = new L.FeatureGroup().addTo(map);

    let replayTimer = null; let currentIndex = 0; let routeData = []; let movingMarker = null;

    frappe.call({ method: 'frappe.client.get_list', args: { doctype: 'Sales Person', fields: ['name'], limit_page_length: 500 },
        callback: function(r) { if (r.message) { let dropdown = document.getElementById('map-person'); r.message.forEach(u => { dropdown.add(new Option(u.name, u.name)); }); } }
    });

    function getDistance(lat1, lon1, lat2, lon2) {
        var p = 0.017453292519943295; var c = Math.cos;
        var a = 0.5 - c((lat2 - lat1) * p)/2 + c(lat1 * p) * c(lat2 * p) * (1 - c((lon2 - lon1) * p))/2;
        return 12742 * Math.asin(Math.sqrt(a)); // Returns distance in KM
    }

    function fetch_locations() {
        if(replayTimer) clearInterval(replayTimer);
        document.getElementById('map-status').innerText = "Fetching data...";
        markersLayer.clearLayers(); routeData = []; currentIndex = 0; if(movingMarker) movingMarker.remove();

        let sDate = document.getElementById('map-start-date').value;
        let eDate = document.getElementById('map-end-date').value;
        let sp = document.getElementById('map-person').value;

        let startDT = `${sDate} 00:00:00`; let endDT = `${eDate} 23:59:59`;
        let filters = [['timestamp', 'between', [startDT, endDT]]];
        let visitFilters = [['start_time', 'between', [startDT, endDT]]];

        if (sp !== "All") { filters.push(['sales_person', '=', sp]); visitFilters.push(['sales_person', '=', sp]); }

        frappe.call({
            method: 'frappe.client.get_list',
            args: { doctype: 'Salesperson Location Log', fields: ['latitude', 'longitude', 'timestamp', 'sales_person'], filters: filters, limit_page_length: 5000, order_by: 'timestamp asc' },
            callback: function(r) {
                let logs = r.message || []; let bounds = []; let latlngs = []; let prevPoint = null;
                let totalDistanceKm = 0;

                logs.forEach((log, index) => {
                    let lat = parseFloat(log.latitude), lng = parseFloat(log.longitude);
                    if (lat && lng) {
                        let status = 'Stationary'; let color = '#ffb300'; // Orange
                        if (prevPoint) {
                            let distKm = getDistance(prevPoint.lat, prevPoint.lng, lat, lng);
                            if (distKm > 0.015) { status = 'Moving'; color = '#1976D2'; totalDistanceKm += distKm; } // Blue
                        }
                        prevPoint = {lat, lng};
                        routeData.push({lat, lng, time: log.timestamp, sp: log.sales_person});
                        latlngs.push([lat, lng]); bounds.push([lat, lng]);

                        // Determine marker style (Hover-only tooltips)
                        let isLast = index === logs.length - 1;
                        let divHtml = `<div style="width:12px; height:12px; background:${color}; border-radius:50%; border:2px solid white; box-shadow:0 0 3px rgba(0,0,0,0.5);"></div>`;
                        if (isLast) divHtml = `<div class="pulse-marker" style="width:16px; height:16px; border:2px solid white;"></div>`;

                        let customIcon = L.divIcon({ className: '', html: divHtml, iconSize: [16,16], iconAnchor: [8,8] });

                        // bindTooltip instead of bindPopup (Hover to see)
                        L.marker([lat, lng], {icon: customIcon})
                         .bindTooltip(`<b>👤 ${log.sales_person}</b><br>🕒 ${log.timestamp}<br>📌 ${status}`, {direction: 'top', className: 'modern-tooltip'})
                         .addTo(markersLayer);
                    }
                });

                document.getElementById('stat-dist').innerText = totalDistanceKm.toFixed(2) + " km";
                document.getElementById('stat-pings').innerText = logs.length;

                if (latlngs.length > 0) L.polyline(latlngs, {color: '#1976D2', weight: 3, opacity: 0.6}).addTo(markersLayer);

                frappe.call({
                    method: 'frappe.client.get_list',
                    args: { doctype: 'Visit Log', fields: ['customer', 'custom_latitude', 'custom_longitude', 'start_time', 'outcome'], filters: visitFilters, limit_page_length: 1000 },
                    callback: function(vRes) {
                        let visits = vRes.message || [];
                        document.getElementById('stat-visits').innerText = visits.length;

                        visits.forEach(v => {
                            let vLat = parseFloat(v.custom_latitude), vLng = parseFloat(v.custom_longitude);
                            if(vLat && vLng) {
                                let color = v.outcome === 'Order Taken' ? '#4CAF50' : '#E53935'; // Green vs Red
                                let vHtml = `<div style="width:18px;height:18px;background:${color};border-radius:50%;border:2px solid white;display:flex;align-items:center;justify-content:center;box-shadow:0 2px 5px rgba(0,0,0,0.4);"><span style="color:white;font-size:10px;">V</span></div>`;
                                let vIcon = L.divIcon({ className: '', html: vHtml, iconSize: [18,18], iconAnchor: [9,9] });

                                L.marker([vLat, vLng], {icon: vIcon})
                                 .bindTooltip(`<b>🏬 ${v.customer}</b><br>Time: ${v.start_time}<br>Outcome: <b>${v.outcome}</b>`, {direction: 'top'})
                                 .addTo(markersLayer);
                                bounds.push([vLat, vLng]);
                            }
                        });
                        if (bounds.length > 0) map.fitBounds(bounds, { padding: [50, 50] });
                        document.getElementById('map-status').innerText = `✅ Data Loaded.`;
                    }
                });
            }
        });
    }

    document.getElementById('btn-refresh-map').addEventListener('click', fetch_locations);

    document.getElementById('btn-play').addEventListener('click', function() {
        if (routeData.length === 0) return frappe.msgprint("No route to play.");
        document.getElementById('map-status').innerText = "▶ Replaying Route...";

        let repHtml = `<div style="width:20px;height:20px;background:#8e24aa;border-radius:50%;border:3px solid white;box-shadow:0 0 10px rgba(0,0,0,0.5);"></div>`;
        let repIcon = L.divIcon({ className: '', html: repHtml, iconSize: [20, 20], iconAnchor: [10, 10] });

        if (!movingMarker) movingMarker = L.marker([routeData[0].lat, routeData[0].lng], {icon: repIcon}).addTo(map);
        if(replayTimer) clearInterval(replayTimer);

        replayTimer = setInterval(() => {
            if (currentIndex >= routeData.length) { clearInterval(replayTimer); document.getElementById('map-status').innerText = "✅ Replay Complete."; return; }
            let pt = routeData[currentIndex];
            movingMarker.setLatLng([pt.lat, pt.lng]);
            movingMarker.bindTooltip(`<b>${pt.sp}</b><br>${pt.time}`).openTooltip();
            currentIndex++;
        }, 300); // 300ms for smoother modern playback
    });

    document.getElementById('btn-pause').addEventListener('click', function() { clearInterval(replayTimer); document.getElementById('map-status').innerText = "⏸ Replay Paused."; });
    document.getElementById('btn-stop').addEventListener('click', function() { clearInterval(replayTimer); currentIndex = 0; if(movingMarker) { movingMarker.remove(); movingMarker = null; } document.getElementById('map-status').innerText = "⏹ Replay Stopped."; });
}
